// Generates the TypeScript and Python contracts from the JSON Schemas in this folder.
//   node schemas/generate.mjs           write the generated files
//   node schemas/generate.mjs --check   fail when the committed files are stale
import { spawnSync } from "node:child_process";
import {
  cpSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { compile } from "json-schema-to-typescript";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const schemaDir = join(root, "schemas");
const BASE = "https://itza.dev/schemas/";

/** Contract schemas, in generation order. `common` only carries shared definitions. */
const NAMES = [
  "common",
  "provenance",
  "canonical-series",
  "field-bundle",
  "engine-input",
  "engine-output",
  "evidence-card",
  "assistant-tools",
];

const TARGETS = {
  ts: join(root, "packages/engine/src/contracts/generated"),
  py: join(root, "services/science-api/src/itza_science/contracts"),
};

const schemas = Object.fromEntries(
  NAMES.map((name) => [
    name,
    JSON.parse(readFileSync(join(schemaDir, `${name}.schema.json`), "utf8")),
  ]),
);

/** Sibling keywords next to a $ref make the type generator emit a duplicate type; drop them. */
function withoutRefSiblings(node) {
  if (Array.isArray(node)) return node.map(withoutRefSiblings);
  if (node && typeof node === "object") {
    const copy = Object.fromEntries(
      Object.entries(node).map(([k, v]) => [k, withoutRefSiblings(v)]),
    );
    if ("$ref" in copy) return { $ref: copy.$ref };
    return copy;
  }
  return node;
}

async function generateTypeScript() {
  const rootSchema = {
    title: "Contracts",
    type: "object",
    additionalProperties: false,
    properties: Object.fromEntries(NAMES.map((n) => [n, { $ref: `${BASE}${n}.schema.json` }])),
    required: NAMES,
  };
  const resolver = {
    order: 1,
    canRead: (file) => file.url.startsWith(BASE),
    read: (file) => {
      const name = file.url.slice(BASE.length).replace(/\.schema\.json.*$/, "");
      return JSON.stringify(withoutRefSiblings(schemas[name]));
    },
  };
  const types = await compile(rootSchema, "Contracts", {
    $refOptions: { resolve: { itza: resolver } },
    additionalProperties: false,
    bannerComment: "// Generated by schemas/generate.mjs from schemas/*.schema.json. Do not edit.",
    format: false,
  });
  const embedded = Object.fromEntries(NAMES.map((n) => [n, schemas[n]]));
  const registry = [
    "// Generated by schemas/generate.mjs from schemas/*.schema.json. Do not edit.",
    `export const schemas = ${JSON.stringify(embedded, null, 2)} as const;`,
    "",
  ].join("\n");
  return { "types.ts": `${types}\n`, "schemas.ts": registry };
}

function generatePython(outDir) {
  // The generated header names the input folder, so its name must not change between runs.
  const scratch = mkdtempSync(join(tmpdir(), "itza-schemas-"));
  const input = join(scratch, "schemas");
  mkdirSync(input);
  try {
    for (const name of NAMES)
      cpSync(join(schemaDir, `${name}.schema.json`), join(input, `${name}.schema.json`));
    const run = spawnSync(
      "uv",
      [
        "run",
        "--project",
        join(root, "services/science-api"),
        "datamodel-codegen",
        "--input",
        input,
        "--input-file-type",
        "jsonschema",
        "--output",
        outDir,
        "--output-model-type",
        "pydantic_v2.BaseModel",
        "--target-python-version",
        "3.12",
        "--use-annotated",
        "--use-standard-collections",
        "--use-union-operator",
        "--use-type-alias",
        "--field-constraints",
        "--disable-timestamp",
        "--formatters",
        "ruff-format",
      ],
      { encoding: "utf8" },
    );
    if (run.status !== 0) throw new Error(`datamodel-codegen failed:\n${run.stderr}`);
  } finally {
    rmSync(scratch, { recursive: true, force: true });
  }
}

const CACHE_DIRS = /__pycache__|\.ruff_cache|\.mypy_cache/;

function readTree(dir) {
  if (!existsSync(dir)) return {};
  return Object.fromEntries(
    readdirSync(dir, { recursive: true, withFileTypes: true })
      .filter((e) => e.isFile() && !CACHE_DIRS.test(e.parentPath))
      .map((e) => {
        const path = join(e.parentPath, e.name);
        return [path.slice(dir.length + 1), readFileSync(path, "utf8")];
      }),
  );
}

function writeTree(dir, files) {
  rmSync(dir, { recursive: true, force: true });
  for (const [rel, content] of Object.entries(files)) {
    mkdirSync(dirname(join(dir, rel)), { recursive: true });
    writeFileSync(join(dir, rel), content);
  }
}

const check = process.argv.includes("--check");
const tmp = mkdtempSync(join(tmpdir(), "itza-contracts-"));
try {
  const ts = await generateTypeScript();
  generatePython(join(tmp, "py"));
  const py = readTree(join(tmp, "py"));
  const next = { ts, py };

  if (check) {
    const stale = [];
    for (const key of ["ts", "py"]) {
      const committed = readTree(TARGETS[key]);
      const names = new Set([...Object.keys(committed), ...Object.keys(next[key])]);
      for (const name of names) {
        if (committed[name] !== next[key][name])
          stale.push(join(TARGETS[key], name).slice(root.length + 1));
      }
    }
    if (stale.length > 0) {
      console.error(
        `Generated contracts are stale. Run "pnpm schemas:generate" and commit:\n  ${stale.join("\n  ")}`,
      );
      process.exit(1);
    }
    console.log("Generated contracts are up to date.");
  } else {
    writeTree(TARGETS.ts, ts);
    writeTree(TARGETS.py, py);
    console.log("Generated contracts written.");
  }
} finally {
  rmSync(tmp, { recursive: true, force: true });
}
